read=lambda n:json.loads((B/(n+'.json')).read_text());reports={n:read(n)for n in ['physics-tests','item-tests','surface-tests','world-tests','browser-tests','offline-tests','unchanged-renders','scope-tests','comparison-report','release-smoke','night-tests']}
for n,r in reports.items():assert r['status']=='passed',n
raw=H.read_bytes();sha=lambda x:hashlib.sha256(x).hexdigest();metrics=read('asset-metrics');assert sha(raw)==metrics['html_sha256'];assert reports['release-smoke']['html_sha256']==sha(raw);assert raw==Path('/tmp/blokraya-6e/candidate.html').read_bytes()
metrics.update({'under_25_decimal_MB':len(raw)<25000000,'reports':{n:len(r.get('checks',[]))for n,r in reports.items()},'teacher_export_bytes':reports['offline-tests']['export_bytes'],'offline_asset_HTTP_requests':len(reports['offline-tests']['assetRequests']),'direct_file_note':read('direct-file-tests').get('reason'),'release_status':'Ready for visual review; reference accuracy and direct file navigation have documented limitations.'})
notes='BLOKRAYA — STAGE 8 YOGYAKARTA: HERITAGE NIGHT RACE (6E)\n\nEkstrak ZIP lalu buka blokraya-stage8-yogyakarta.html pada browser modern dengan WebGL. Seluruh aset tertanam. Gunakan browser/profil/origin sama agar data lokal lama terbaca. Mode Siswa tanpa PIN; Mode Guru memakai PIN lokal. Klik/sentuh untuk audio.\n\nDelapan arena playable: Pontianak, Mempawah, Singkawang, Sambas, Sintang, Kapuas Hulu, Bengkayang dan Yogyakarta. Bali/Bromo tetap Segera Hadir. Kalbar Klasik tetap tiga arena awal; Nusantara menunggu dua world terakhir. Tidak memberikan token/unlock QA pada distribusi.\n\nJalur kota fiktif 826,23 m pada malam hari, monumen putih-emas terinspirasi Tugu Pal Putih, taman/plaza, koridor pertokoan bernuansa Malioboro, lampu hangat, bangku, pepohonan kota dan gerobak dekoratif. Ini interpretasi stylized, bukan rekonstruksi geografis/arsitektur. Akses referensi web ditolak HTTP 403; proporsi, ornamen dan denah belum diverifikasi dari foto.\n\nLangit malam memakai gradient/awan ringan yang sudah ada, satu shader awan scoped, satu batch bulan/bintang dan cahaya jalan dekoratif tanpa point-light dinamis. Material GLB dipulihkan setiap frame, garasi tetap netral dan semua animasi memakai clock simulasi lama. Kuis membekukan simulasi. Nilai akademik terpisah dari hasil balapan.\n\nOffline lulus dengan jaringan browser dimatikan dan dokumen lokal disuplai harness pada localhost, tanpa request HTTP/CDN aset. Navigasi file:// benar-benar dicoba tetapi diblokir administrator cloud; perlu verifikasi di browser target. HP fisik/FPS/frame time/memori belum diukur. Tidak menambahkan server wajib atau loader fetch aset lokal.\n\nKontrol: A/D/panah, W/S gas/rem, C drift, Shift jump, E/Spasi buff, Q/1/2 slot, P/Esc jeda, serta kontrol sentuh. ID penyimpanan/progres/bank soal/PIN tetap.\n\nReview ZIP memuat sumber builder JavaScript/track/metadata, screenshot renderer asli, thumbnail dan hasil uji/metrik. Build ulang memerlukan checkout baseline Bengkayang, lihat README. Blender tersedia tetapi tidak diperlukan untuk geometri prosedural ini.\n\nTidak merge ke main, mengubah index.html, deployment atau mengerjakan 6F.\n'
for kind in ['playable','review']:
 dest=R/f'blokraya-stage8-yogyakarta-{kind}.zip'
 with zipfile.ZipFile(dest,'w',zipfile.ZIP_DEFLATED,compresslevel=9)as z:
  z.write(H,H.name);z.writestr('MULAI.txt',notes)
  if kind=='review':
   for f in sorted(B.rglob('*')):
    if f.is_file()and '__pycache__'not in f.parts and f.name!='release-metrics.json':z.write(f,'stage8-yogyakarta/'+f.relative_to(B).as_posix())
   z.writestr('stage8-yogyakarta/release-metrics.json',json.dumps({**metrics,'review_self_hash_omitted':True,'review_self_hash_note':'The full review ZIP hash lives in the repository release-metrics.json; an archive cannot contain its own final hash.'},indent=2))
 with zipfile.ZipFile(dest)as z:assert z.testzip()is None;assert z.read(H.name)==raw;entries=len(z.namelist())
 metrics[kind+'_zip']={'file':dest.name,'bytes':dest.stat().st_size,'sha256':sha(dest.read_bytes()),'crc_ok':True,'html_identical':True,'entries':entries}
(B/'release-metrics.json').write_text(json.dumps(metrics,indent=2));print(json.dumps({k:metrics[k]for k in ['html_bytes','growth_bytes','html_sha256','playable_zip','review_zip']},indent=2))
